<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/runtime.php';
require_once __DIR__ . '/../includes/cotizaciones.php';
require_once __DIR__ . '/../includes/company.php';
require_auth();

$id=(int)($_GET['id']??0);
$quote=quote_get($id);
if(!$quote){http_response_code(404);exit('Cotización no encontrada.');}
$company=company_profile();
$items=quote_items($id);
$totals=quote_totals($id);

function cp_escape(string $v): string { return htmlspecialchars($v,ENT_QUOTES,'UTF-8'); }
function cp_advance(?string $terms): ?float {
    if(!$terms) return null;
    if(preg_match('/(\d+(?:[.,]\d+)?)\s*%/', $terms,$m)){
        $p=(float)str_replace(',','.',$m[1]); return ($p>=0&&$p<=100)?$p:null;
    }
    return null;
}
$money=static fn(float $n):string=>'$'.number_format($n,2,'.',',');
$total=(float)$totals['total']; $pct=cp_advance((string)($quote['payment_terms']??''));
$advance=$pct!==null?round($total*$pct/100,2):null; $balance=$advance!==null?round($total-$advance,2):null;
$brand=(string)($company['trade_name']?:$company['legal_name']); $logo=(string)($company['logo_path']??''); $paymentInfo=trim((string)($company['payment_info']??''));
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Cotización <?=cp_escape((string)$quote['quote_number'])?></title>
<style>
@page{size:Letter;margin:12mm 14mm}*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:#17212b;background:#e9eef3;font-size:10pt}.sheet{width:215.9mm;min-height:279.4mm;margin:0 auto 10mm;padding:12mm 14mm;background:#fff;position:relative;page-break-after:always}.sheet:last-child{page-break-after:auto}.accent{height:3px;background:#ec0b63;margin:-12mm -14mm 7mm}.teal{background:#16b7a4}.header{display:flex;justify-content:space-between;align-items:flex-start}.brand{display:flex;gap:10px;align-items:center}.brand img{width:42mm;max-height:20mm;object-fit:contain}.brand strong{display:block;font-size:16pt;color:#0b2239}.brand small{color:#667085}.title{text-align:right}.eyebrow,.label{font-size:7.5pt;letter-spacing:.1em;text-transform:uppercase;color:#667085;font-weight:800}.title h1{margin:3px 0;font-size:24pt;color:#0b2239}.title p{margin:0;color:#667085;font-size:8pt}.grid3{display:grid;grid-template-columns:40mm 1fr 50mm;margin-top:5mm;background:#f4f7fa;border:1px solid #d9e1e8}.grid3>div{padding:3.5mm;border-right:1px solid #d9e1e8}.grid3>div:last-child{border-right:0}.value{margin-top:2px;font-size:8.7pt}.box{border:1px solid #d9e1e8;padding:4mm;margin-top:4mm}.client{font-size:13pt;font-weight:800;color:#0b2239;margin-top:2px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:4px 15px;margin-top:5px;color:#4f5b67;font-size:8.5pt}.refs{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;border-top:1px solid #d9e1e8;border-bottom:1px solid #d9e1e8;padding:3.5mm 0;margin-top:4mm}.refs strong{display:block;margin-top:2px;font-size:8pt;color:#17212b}table{width:100%;border-collapse:collapse;margin-top:5mm}th{background:#0b2239;color:#fff;text-align:left;padding:7px;font-size:7.8pt}td{border-bottom:1px solid #d9e1e8;padding:7px;font-size:8.5pt;vertical-align:top}th:not(:first-child),td:not(:first-child){text-align:right}.totals{width:48%;margin-left:auto;margin-top:3mm}.totals div{display:flex;justify-content:space-between;padding:4px}.grand{border-top:2px solid #16b7a4;padding-top:7px!important;font-size:14pt;font-weight:800;color:#0b2239}.section{border-top:1px solid #d9e1e8;margin-top:5mm;padding-top:3mm}.section h3{margin:0 0 4px;color:#0b2239;font-size:9.5pt}.section p{margin:0;color:#596675;font-size:8.5pt}.footer{position:absolute;left:14mm;right:14mm;bottom:6mm;border-top:1px solid #16b7a4;padding-top:3px;color:#667085;font-size:7pt;display:flex;justify-content:space-between}.summary{margin-top:8mm;border:1px solid #d9e1e8}.row{display:flex;justify-content:space-between;padding:11px 13px;border-bottom:1px solid #d9e1e8}.head{background:#0b2239;color:#fff;font-weight:800;font-size:7.8pt}.advance{background:#e8fbf8}.advance strong{font-size:18pt;color:#0b2239}.paybox{margin-top:8mm;border:2px solid #16b7a4;background:#f4f7fa;padding:6mm}.paybox h2{margin:0 0 5px;color:#0b2239;font-size:13pt}.bank{margin-top:8mm;padding:5mm;background:#f4f7fa;border:1px solid #d9e1e8;white-space:pre-line;color:#44515e;font-size:8.7pt}.closing{margin-top:8mm;background:#0b2239;color:#fff;padding:5mm;display:grid;grid-template-columns:1fr 1fr 1fr}.closing span{display:block;font-size:7pt;opacity:.75;text-transform:uppercase}.closing strong{display:block;margin-top:2px;font-size:11pt}
@media print{body{background:#fff}.sheet{width:auto;min-height:0;margin:0;padding:0;box-shadow:none}.accent{margin:0 0 7mm}.footer{position:fixed}}
</style></head><body>
<section class="sheet"><div class="accent"></div>
<div class="header"><div class="brand"><?php if($logo):?><img src="<?=cp_escape($logo)?>" alt="logo"><?php endif;?><div><strong><?=cp_escape($brand)?></strong><small><?=cp_escape((string)$company['legal_name'])?></small></div></div><div class="title"><div class="eyebrow">COTIZACIÓN</div><h1><?=cp_escape((string)$quote['quote_number'])?></h1><p>Fecha: <?=cp_escape(date('d/m/Y',strtotime((string)$quote['issue_date'])))?><?php if($quote['valid_until']):?> · Vigencia: <?=cp_escape(date('d/m/Y',strtotime((string)$quote['valid_until'])))?><?php endif;?></p></div></div>
<div class="grid3"><div><div class="label">RFC</div><div class="value"><?=cp_escape((string)$company['rfc'])?></div></div><div><div class="label">Domicilio</div><div class="value"><?=cp_escape(trim((string)$company['address'].' '.(string)$company['neighborhood']))?><br><?=cp_escape(trim((string)$company['city'].' '.(string)$company['state'].' C.P. '.(string)$company['postal_code']))?></div></div><div><div class="label">Contacto</div><div class="value"><?=cp_escape((string)$company['phone'])?><br><?=cp_escape((string)$company['email'])?></div></div></div>
<div class="box"><div class="eyebrow">DATOS DEL CLIENTE</div><div class="client"><?=cp_escape((string)($quote['customer_name']??'Sin cliente'))?></div><div class="meta"><?php if($quote['customer_tax_number']):?><div><b>RFC:</b> <?=cp_escape((string)$quote['customer_tax_number'])?></div><?php endif;?><?php if($quote['customer_phone']):?><div><b>Teléfono:</b> <?=cp_escape((string)$quote['customer_phone'])?></div><?php endif;?><?php if($quote['customer_email']):?><div><b>Correo:</b> <?=cp_escape((string)$quote['customer_email'])?></div><?php endif;?><?php if($quote['customer_address']):?><div><b>Domicilio:</b> <?=cp_escape((string)$quote['customer_address'])?></div><?php endif;?></div></div>
<div class="refs"><?php foreach([['Referencia',$quote['client_reference']],['Pago',$quote['payment_terms']],['Entrega',$quote['delivery_time']],['Lugar',$quote['delivery_place']]] as $r):?><div><?php if(trim((string)$r[1])!==''):?><div class="label"><?=cp_escape((string)$r[0])?></div><strong><?=cp_escape((string)$r[1])?></strong><?php endif;?></div><?php endforeach;?></div>
<table><thead><tr><th>Descripción</th><th>Cant.</th><th>Precio unit.</th><th>Importe</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=cp_escape((string)$item['description'])?></td><td><?=cp_escape((string)$item['quantity'])?></td><td><?=$money((float)$item['unit_price'])?></td><td><?=$money((float)$item['subtotal'])?></td></tr><?php endforeach;?></tbody></table>
<div class="totals"><div>Subtotal <b><?=$money((float)$totals['subtotal'])?></b></div><div>Descuento <b><?=$money((float)$totals['discount'])?></b></div><div>Impuestos <b><?=$money((float)$totals['tax'])?></b></div><div class="grand">Total <b><?=$money($total)?></b></div></div>
<?php if($quote['notes']):?><div class="section"><h3>Notas</h3><p><?=nl2br(cp_escape((string)$quote['notes']))?></p></div><?php endif;?>
<div class="footer"><span><?=cp_escape($brand)?> · <?=cp_escape((string)$quote['quote_number'])?></span><span>Página 1 de 2</span></div></section>
<section class="sheet"><div class="accent teal"></div><div class="eyebrow">RESUMEN FINANCIERO</div><div class="title" style="text-align:left"><h1>Resumen de pago</h1><p>Información de pago de la cotización <?=cp_escape((string)$quote['quote_number'])?></p></div>
<div class="summary"><div class="row head"><span>CONCEPTO</span><span>IMPORTE</span></div><div class="row"><span>Total de la cotización</span><b><?=$money($total)?></b></div><div class="row advance"><span><b>Pago anticipado<?= $pct!==null?' · '.rtrim(rtrim(number_format($pct,2,'.',''),'0'),'.').'%' : ''?></b></span><strong><?= $advance!==null?$money($advance):'Por definir'?></strong></div><div class="row"><span>Saldo pendiente</span><b><?= $balance!==null?$money($balance):'Por definir'?></b></div></div>
<div class="paybox"><h2>Pago anticipado</h2><div><?php if($advance!==null):?>Para iniciar la producción se requiere un anticipo de <b><?=$money($advance)?></b>. El saldo restante es de <b><?=$money($balance)?></b>.<?php else:?>Las condiciones de esta cotización no especifican un porcentaje de anticipo. El monto deberá confirmarse antes de iniciar la producción.<?php endif;?></div></div>
<div class="section"><div class="eyebrow">DATOS PARA REALIZAR EL ANTICIPO</div><?php if($paymentInfo):?><div class="bank"><?=cp_escape($paymentInfo)?></div><?php else:?><div class="bank">No se han configurado datos bancarios en el perfil de la empresa.</div><?php endif;?></div>
<?php if($quote['terms']):?><div class="section"><h3>Condiciones comerciales</h3><p><?=nl2br(cp_escape((string)$quote['terms']))?></p></div><?php endif;?>
<div class="closing"><div><span>Cotización</span><strong><?=cp_escape((string)$quote['quote_number'])?></strong></div><div><span>Total</span><strong><?=$money($total)?></strong></div><div><span>Anticipo</span><strong><?= $advance!==null?$money($advance):'Por definir'?></strong></div></div>
<div class="footer"><span><?=cp_escape($brand)?> · <?=cp_escape((string)$quote['quote_number'])?></span><span>Página 2 de 2</span></div></section></body></html>
